# PawPath booking flow for Harbor Street (mobile, 375 px)

## 1. Prototype

Save the code as an `.html` file and open it at 375 px width. The script checks the raw slot data against the clinic rules, so only bookable slots appear. The browser console lists each rejected slot and the reason it was rejected.

```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Book a visit – PawPath Harbor Street</title>
<style>
  :root{
    --primary:#7FD1AE;
    --on-primary:#1D2B33;   /* DEPARTURE: brand asks #FFFFFF (1.8:1, fails). Ink = 8.1:1 */
    --ink:#1D2B33;
    --surface:#FFFFFF;
    --muted:#5E6B73;        /* 5.5:1 on white; never placed on --primary (3.0:1) */
    --tint:#EAF7F1;         /* ADDED: light primary tint for selected/updated states */
    --line:#D5DADD;         /* decorative dividers only */
    --radius:12px;
    --font:system-ui, sans-serif;
    --body:16px;
    --bar-h:140px;          /* updated from JS to the real summary-bar height */
  }
  *{box-sizing:border-box}
  html{scroll-padding-top:16px;scroll-padding-bottom:calc(var(--bar-h) + 16px)} /* WCAG 2.4.11: sticky bar never hides focus */
  body{margin:0;font:var(--body)/1.5 var(--font);color:var(--ink);background:var(--surface)}
  .vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
  .wrap{max-width:480px;margin:0 auto;padding:0 16px}
  :focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  [tabindex="-1"]:focus{outline:none}

  header.top{border-bottom:1px solid var(--line);padding:12px 0}
  .brand{margin:0;font-weight:800;font-size:18px}
  .brand span{display:inline-block;width:12px;height:12px;border-radius:50%;background:var(--primary);margin-right:6px;vertical-align:middle}
  .clinic{margin:2px 0 0;font-size:14px}
  .muted{color:var(--muted)}

  main{padding:16px 0 calc(var(--bar-h) + 24px)}
  h1{font-size:24px;line-height:1.25;margin:4px 0 4px}
  .lede{margin:0 0 16px;color:var(--muted)}

  .step{border:1px solid var(--line);border-radius:var(--radius);padding:16px;margin-bottom:12px}
  .step h2{font-size:18px;margin:0 0 8px;display:flex;align-items:center;gap:8px}
  .num{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;
       background:var(--primary);color:var(--ink);font-size:14px;font-weight:700}
  .step.locked h2{color:var(--muted)}
  .step.locked .num{background:var(--surface);border:1px solid var(--muted);color:var(--muted)}
  .grp{font-size:14px;font-weight:700;margin:12px 0 6px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}

  .opt{display:flex;justify-content:space-between;align-items:center;gap:12px;width:100%;min-height:56px;
       padding:12px 14px;margin:0 0 8px;border:1px solid var(--muted);border-radius:var(--radius);
       background:var(--surface);color:var(--ink);font:inherit;text-align:left;cursor:pointer}
  .opt[aria-pressed="true"]{background:var(--tint);border:2px solid var(--ink);padding:11px 13px}
  .opt[aria-pressed="true"] .opt-title::before{content:"✓ ";font-weight:800}
  .opt-title{display:block;font-weight:700}
  .opt-meta{display:block;color:var(--muted);font-size:14px}
  .opt-price{font-weight:700;white-space:nowrap}

  .picked{display:flex;justify-content:space-between;align-items:center;gap:8px}
  .link{background:none;border:0;color:var(--ink);text-decoration:underline;font:inherit;font-weight:600;
        min-height:44px;min-width:44px;padding:0 6px;cursor:pointer}
  .day{margin:0 0 4px}
  .empty{border:1px dashed var(--muted);border-radius:var(--radius);padding:12px 14px}
  .empty p{margin:0 0 8px}

  .btn{display:block;width:100%;min-height:48px;border-radius:var(--radius);font:inherit;font-weight:700;
       border:0;cursor:pointer;padding:10px 16px}
  .primary{background:var(--primary);color:var(--on-primary)}
  .secondary{background:var(--surface);color:var(--ink);border:2px solid var(--ink)}
  .btn + .btn{margin-top:10px}

  .card{border:1px solid var(--line);border-radius:var(--radius);padding:4px 16px;margin:16px 0}
  .details{margin:0}
  .details div{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--line)}
  .details div:last-child{border-bottom:0}
  .details dt{color:var(--muted)}
  .details dd{margin:0;text-align:right;font-weight:600}
  .details .price dd{font-size:20px;font-weight:800}
  .note{background:var(--tint);border-radius:var(--radius);padding:12px 14px;margin:0 0 16px;font-size:15px}
  .ok{display:inline-grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--primary);
      color:var(--ink);font-size:26px;font-weight:800;margin-top:8px}

  /* design annotation, not product UI */
  .proto-note{border:2px dashed #B04A00;color:#7A3300;background:#FFF6EE;border-radius:8px;padding:8px 10px;font-size:13px;margin:8px 0}

  /* Sticky booking summary */
  .bar{position:fixed;left:0;right:0;bottom:0;background:var(--surface);border-top:2px solid var(--ink);
       box-shadow:0 -4px 12px rgba(29,43,51,.12);padding:10px 0 calc(12px + env(safe-area-inset-bottom))}
  .sum-label{margin:0;font-size:13px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
  .sum-top{display:flex;justify-content:space-between;gap:8px;font-weight:700;margin:2px 0 0}
  .sum-sub{font-size:14px;color:var(--muted);margin:0 0 8px}
  .chg{background:var(--tint);color:var(--ink);border-radius:4px;padding:0 2px}
  .upd{display:inline-block;margin-left:4px;padding:0 6px;border:1px solid var(--ink);border-radius:999px;
       font-size:13px;font-weight:700;color:var(--ink);line-height:1.4;vertical-align:1px}
  .hint{margin:0;font-size:14px;padding:12px;border-radius:var(--radius);border:1px dashed var(--muted);text-align:center}
  @media (prefers-reduced-motion:no-preference){
    .chg{animation:flash 1.2s ease-out}
    @keyframes flash{from{background:var(--primary)}to{background:var(--tint)}}
  }
</style>
</head>
<body>
<header class="top">
  <div class="wrap">
    <p class="brand"><span aria-hidden="true"></span>PawPath</p>
    <p class="clinic"><strong>Harbor Street clinic</strong><br>
      <span class="muted">12 Harbor Street, Example City · Mon–Sat 09:00–17:00, closed 12:00–13:00</span></p>
  </div>
</header>

<main id="app" class="wrap"></main>

<section class="bar" id="bar" aria-labelledby="bar-h">
  <div class="wrap" id="bar-inner"></div>
</section>

<div id="live" class="vh" aria-live="polite"></div>

<script>
/* ---------- Data ---------- */
const CLINIC = { name:"PawPath Harbor Street", address:"12 Harbor Street, Example City",
  open:"09:00", close:"17:00", lunch:["12:00","13:00"], days:["Mon","Tue","Wed","Thu","Fri","Sat"] };

const SERVICES = [
  { id:"wellness",    name:"Wellness exam",       mins:30, price:65,  priceIsFrom:false, vets:"any",    popular:true },
  { id:"vaccination", name:"Vaccination visit",   mins:15, price:40,  priceIsFrom:false, vets:"any",    popular:true },
  { id:"dental",      name:"Dental cleaning",     mins:90, price:280, priceIsFrom:true,  vets:["mary"], popular:false },
  { id:"exotic",      name:"Exotic pet check-up", mins:45, price:85,  priceIsFrom:false, vets:["mary"], popular:false }
];

const VETS = {
  mary:    { name:"Dr. Mary Major",    days:["Tue","Thu","Sat"], daysLabel:"Tue, Thu, Sat" },
  richard: { name:"Dr. Richard Miles", days:["Mon","Tue","Wed","Thu","Fri","Sat"], daysLabel:"Mon–Sat" }
};

/* Raw API response, unchanged */
const RAW_SLOTS = [
  {"vet":"Richard Miles","service":"Exotic pet check-up","start":"10:00"},
  {"vet":"Mary Major","service":"Exotic pet check-up","start":"11:00"},
  {"vet":"Mary Major","service":"Dental cleaning","start":"11:30"},
  {"vet":"Richard Miles","service":"Wellness exam","start":"12:30"},
  {"vet":"Richard Miles","service":"Wellness exam","start":"14:00"},
  {"vet":"Mary Major","service":"Wellness exam","start":"16:45"}
];
const DAY = "Thu";
const DATE_LABEL = "Thursday";   // API gives no calendar date – see data problems

/* ---------- Helpers ---------- */
const $ = s => document.querySelector(s);
const toMin = t => { const [h,m] = t.split(":").map(Number); return h*60 + m; };
const fmt = m => String(Math.floor(m/60)).padStart(2,"0") + ":" + String(m%60).padStart(2,"0");
const svcById = id => SERVICES.find(s => s.id === id);
const priceText = s => (s.priceIsFrom ? "from $" : "$") + s.price;
const vetIdFromName = n => Object.keys(VETS).find(id => VETS[id].name.replace(/^Dr\.\s*/,"") === n.trim());

/* ---------- Validate slots against clinic rules (safety net; API should do this) ---------- */
function validate(raw){
  const vet = vetIdFromName(raw.vet);
  const svc = SERVICES.find(s => s.name === raw.service);
  if (!vet) return { ok:false, reason:"Unknown vet" };
  if (!svc) return { ok:false, reason:"Unknown service" };
  if (svc.vets !== "any" && !svc.vets.includes(vet)) return { ok:false, reason:`${VETS[vet].name} does not perform ${svc.name}` };
  if (!CLINIC.days.includes(DAY) || !VETS[vet].days.includes(DAY)) return { ok:false, reason:"Vet not working that day" };
  const start = toMin(raw.start), end = start + svc.mins;
  if (start < toMin(CLINIC.open)) return { ok:false, reason:"Starts before opening" };
  if (end > toMin(CLINIC.close))  return { ok:false, reason:`Ends ${fmt(end)}, after 17:00 closing` };
  const [ls, le] = CLINIC.lunch.map(toMin);
  if (start < le && end > ls) return { ok:false, reason:`${fmt(start)}–${fmt(end)} overlaps lunch closure` };
  return { ok:true, slot:{ id:`${vet}-${svc.id}-${raw.start}`, vet, service:svc.id, start, end } };
}
const CHECKED = RAW_SLOTS.map(r => ({ raw:r, ...validate(r) }));
const SLOTS = CHECKED.filter(c => c.ok).map(c => c.slot);
console.table(CHECKED.filter(c => !c.ok).map(c => ({ ...c.raw, rejected:c.reason })));

/* ---------- State ---------- */
const state = { service:null, vet:null, vetLocked:false, slot:null, open:"service", screen:"pick" };
const changed = new Set();
let changeTimer;

function slotsFor(){
  if (!state.service) return [];
  let list = SLOTS.filter(s => s.service === state.service && (state.vet === "any" || s.vet === state.vet));
  if (state.vet === "any") { const seen = new Set(); list = list.filter(s => !seen.has(s.start) && seen.add(s.start)); }
  return list.sort((a,b) => a.start - b.start);
}

function announce(msg){
  const live = $("#live"); live.textContent = "";
  setTimeout(() => { live.textContent = msg; }, 60);
}
function markChanged(keys){
  keys.forEach(k => changed.add(k));
  clearTimeout(changeTimer);
  changeTimer = setTimeout(() => { changed.clear(); renderBar(); }, 3000);
}

/* ---------- Actions ---------- */
function chooseService(id){
  const svc = svcById(id), msgs = [], keys = ["service","price"];
  const prevService = state.service, prevVet = state.vet;
  state.service = id;
  if (svc.vets !== "any") { state.vet = svc.vets[0]; state.vetLocked = true; }
  else if (state.vetLocked || !state.vet) { state.vet = "any"; state.vetLocked = false; }
  if (state.vet !== prevVet) { keys.push("vet"); msgs.push(state.vetLocked ? `Vet set to ${VETS[state.vet].name}, the only vet for this service` : "Vet: any available vet"); }
  if (state.slot && prevService !== id) { msgs.push(`Time ${fmt(state.slot.start)} cleared, choose a new time`); state.slot = null; keys.push("time"); }
  state.open = null;
  markChanged(keys);
  render();
  const n = slotsFor().length;
  msgs.push(n ? `${n} time${n>1?"s":""} available on ${DATE_LABEL}` : `No openings on ${DATE_LABEL}`);
  announce(`Summary updated. Service: ${svc.name}, ${priceText(svc)}. ${msgs.join(". ")}.`);
  $("#h-time").focus();
}

function chooseVet(id){
  const msgs = [], keys = ["vet"];
  state.vet = id;
  if (state.slot && id !== "any" && state.slot.vet !== id) { msgs.push(`Time ${fmt(state.slot.start)} cleared, it was with another vet`); state.slot = null; keys.push("time"); }
  state.open = null;
  markChanged(keys);
  render();
  const n = slotsFor().length;
  msgs.push(n ? `${n} time${n>1?"s":""} available` : `No openings on ${DATE_LABEL} with this choice`);
  announce(`Summary updated. Vet: ${id === "any" ? "any available vet" : VETS[id].name}. ${msgs.join(". ")}.`);
  $("#h-time").focus();
}

function chooseSlot(id){
  state.slot = SLOTS.find(s => s.id === id);
  markChanged(["time","vet"]);
  render();
  const s = state.slot;
  announce(`Summary updated. ${DATE_LABEL} ${fmt(s.start)} to ${fmt(s.end)} with ${VETS[s.vet].name}. Review booking is now available.`);
  $("#review-btn").focus();
}

document.addEventListener("click", e => {
  const b = e.target.closest("[data-action]"); if (!b) return;
  const { action, id } = b.dataset;
  if (action === "service") chooseService(id);
  if (action === "vet") chooseVet(id);
  if (action === "slot") chooseSlot(id);
  if (action === "open") { state.open = id; render(); $(`#h-${id}`).focus(); }
  if (action === "review") { state.screen = "review"; render(); $("#h-page").focus(); window.scrollTo(0,0); }
  if (action === "edit") { state.screen = "pick"; state.open = null; render(); $("#h-time").focus(); }
  if (action === "confirm") { state.screen = "done"; render(); $("#h-page").focus(); window.scrollTo(0,0); }   // real app: POST + handle 409
  if (action === "restart") { Object.assign(state,{service:null,vet:null,vetLocked:false,slot:null,open:"service",screen:"pick"}); render(); $("#h-page").focus(); }
});

/* ---------- Rendering ---------- */
const head = (id, n, label) => `<h2 id="h-${id}" tabindex="-1"><span class="num" aria-hidden="true">${n}</span>${label}</h2>`;

function sectionService(svc){
  if (state.open !== "service" && svc) return `
    <section class="step" aria-labelledby="h-service">${head("service",1,"Service")}
      <div class="picked"><div><strong>${svc.name}</strong><span class="opt-meta">${svc.mins} min · ${priceText(svc)}</span></div>
      <button class="link" data-action="open" data-id="service">Change<span class="vh"> service</span></button></div>
    </section>`;
  const opt = s => `
    <button class="opt" data-action="service" data-id="${s.id}" aria-pressed="${state.service === s.id}">
      <span><span class="opt-title">${s.name}</span><span class="opt-meta">${s.mins} min · ${s.vets === "any" ? "any vet" : "Dr. Mary Major"}</span></span>
      <span class="opt-price">${priceText(s)}</span>
    </button>`;
  return `
    <section class="step" aria-labelledby="h-service">${head("service",1,"Service")}
      <h3 class="grp" id="g-pop">Most booked</h3>
      <div role="group" aria-labelledby="g-pop">${SERVICES.filter(s => s.popular).map(opt).join("")}</div>
      <h3 class="grp" id="g-spec">With Dr. Mary Major only</h3>
      <div role="group" aria-labelledby="g-spec">${SERVICES.filter(s => !s.popular).map(opt).join("")}</div>
    </section>`;
}

function sectionVet(svc){
  if (!svc) return `<section class="step locked" aria-labelledby="h-vet">${head("vet",2,"Vet")}<p class="muted" style="margin:0">Choose a service first.</p></section>`;
  if (state.vetLocked) return `
    <section class="step" aria-labelledby="h-vet">${head("vet",2,"Vet")}
      <div><strong>${VETS.mary.name}</strong><span class="opt-meta">The only vet who performs ${svc.name.toLowerCase()}</span></div>
    </section>`;
  if (state.open !== "vet") return `
    <section class="step" aria-labelledby="h-vet">${head("vet",2,"Vet")}
      <div class="picked"><div><strong>${state.vet === "any" ? "Any available vet" : VETS[state.vet].name}</strong>
        <span class="opt-meta">${state.vet === "any" ? "Shows the most times" : "Works " + VETS[state.vet].daysLabel}</span></div>
      <button class="link" data-action="open" data-id="vet">Change<span class="vh"> vet</span></button></div>
    </section>`;
  const o = (id, title, meta) => `
    <button class="opt" data-action="vet" data-id="${id}" aria-pressed="${state.vet === id}">
      <span><span class="opt-title">${title}</span><span class="opt-meta">${meta}</span></span></button>`;
  return `
    <section class="step" aria-labelledby="h-vet">${head("vet",2,"Vet")}
      <div role="group" aria-labelledby="h-vet">
        ${o("any","Any available vet","Shows the most times")}
        ${o("mary",VETS.mary.name,"Works "+VETS.mary.daysLabel)}
        ${o("richard",VETS.richard.name,"Works "+VETS.richard.daysLabel)}
      </div>
    </section>`;
}

function sectionTime(svc){
  if (!svc) return `<section class="step locked" aria-labelledby="h-time">${head("time",3,"Time")}<p class="muted" style="margin:0">Choose a service first.</p></section>`;
  if (state.open) return `
    <section class="step" aria-labelledby="h-time">${head("time",3,"Time")}
      <p class="muted" style="margin:0">${state.slot ? `${DATE_LABEL} ${fmt(state.slot.start)}–${fmt(state.slot.end)}` : "Finish the step above to see times."}</p>
    </section>`;
  const list = slotsFor();
  let body;
  if (!list.length) {
    const canWiden = state.vet !== "any" && svc.vets === "any" && SLOTS.some(s => s.service === svc.id);
    body = `<div class="empty">
      <p><strong>No ${svc.name.toLowerCase()} openings on ${DATE_LABEL}${state.vet !== "any" && !state.vetLocked ? ` with ${VETS[state.vet].name}` : ""}.</strong></p>
      ${canWiden
        ? `<button class="btn secondary" data-action="vet" data-id="any">Show any available vet</button>`
        : `<p class="muted">Clinic hours: Mon–Sat, 09:00–17:00 (closed 12:00–13:00).</p>
           <p class="proto-note">Prototype: only Thursday's slots exist in the data. Live app: offer the next day with openings as a one-tap button here.</p>`}
    </div>`;
  } else {
    const grp = (label, items) => items.length ? `<h3 class="grp" id="g-${label}">${label}</h3>
      <div role="group" aria-labelledby="g-${label}">${items.map(s => `
        <button class="opt" data-action="slot" data-id="${s.id}" aria-pressed="${!!state.slot && state.slot.id === s.id}">
          <span><span class="opt-title">${fmt(s.start)}</span><span class="opt-meta">until ${fmt(s.end)} · ${VETS[s.vet].name}</span></span>
        </button>`).join("")}</div>` : "";
    body = grp("Morning", list.filter(s => s.start < 720)) + grp("Afternoon", list.filter(s => s.start >= 720));
  }
  return `
    <section class="step" aria-labelledby="h-time">${head("time",3,"Time")}
      <p class="day"><strong>${DATE_LABEL}</strong> <span class="muted">· ${svc.mins}-minute visit</span></p>
      ${body}
    </section>`;
}

function details(){
  const svc = svcById(state.service), s = state.slot;
  return `<div class="card"><dl class="details">
    <div><dt>Service</dt><dd>${svc.name}<br><span class="muted" style="font-weight:400">${svc.mins} min</span></dd></div>
    <div><dt>Date</dt><dd>${DATE_LABEL}</dd></div>
    <div><dt>Time</dt><dd>${fmt(s.start)}–${fmt(s.end)}</dd></div>
    <div><dt>Vet</dt><dd>${VETS[s.vet].name}</dd></div>
    <div><dt>Clinic</dt><dd>${CLINIC.name}<br>${CLINIC.address}</dd></div>
    <div class="price"><dt>Price</dt><dd>${priceText(svc)}</dd></div>
  </dl></div>
  ${svc.priceIsFrom ? `<p class="note"><strong>Why “from”?</strong> ${svc.name} starts at $${svc.price}. The final price depends on the treatment your pet needs. The vet discusses any extra cost with you before doing more work.</p>` : ""}
  <p class="proto-note">Prototype: the slot API returns only “Thursday”, with no calendar date. Production must show the full date, for example “Thu 6 June”.</p>`;
}

function render(){
  const app = $("#app"), svc = state.service && svcById(state.service);
  if (state.screen === "pick") {
    app.innerHTML = `<h1 id="h-page" tabindex="-1">Book a visit</h1>
      <p class="lede">Pick a service, vet and time, then review before booking.</p>
      ${sectionService(svc)}${sectionVet(svc)}${sectionTime(svc)}`;
  } else if (state.screen === "review") {
    app.innerHTML = `<h1 id="h-page" tabindex="-1">Review your booking</h1>
      <p class="lede">Nothing is booked until you confirm.</p>
      ${details()}
      <button class="btn primary" data-action="confirm">Confirm booking · ${priceText(svc)}</button>
      <button class="btn secondary" data-action="edit">Edit booking</button>`;
  } else {
    app.innerHTML = `<div class="ok" aria-hidden="true">✓</div>
      <h1 id="h-page" tabindex="-1">You're booked</h1>
      <p class="lede">Please arrive a few minutes early at the Harbor Street clinic.</p>
      ${details()}
      <button class="btn secondary" data-action="restart">Book another visit</button>`;
  }
  renderBar();
}

function renderBar(){
  const bar = $("#bar"), inner = $("#bar-inner");
  if (state.screen !== "pick") { bar.hidden = true; setBarHeight(); return; }
  bar.hidden = false;
  const svc = state.service && svcById(state.service);
  const mark = (k, text) => changed.has(k)
    ? `<span class="chg">${text}</span><span class="upd" aria-hidden="true">Updated</span>` : text;
  const vetText = !svc ? "No vet yet"
    : state.slot ? VETS[state.slot.vet].name + (state.vet === "any" ? " (assigned)" : "")
    : state.vet === "any" ? "Any available vet" : VETS[state.vet].name;
  const timeText = state.slot ? `Thu ${fmt(state.slot.start)}–${fmt(state.slot.end)}` : "No time yet";
  inner.innerHTML = `
    <h2 id="bar-h" class="sum-label">Your booking</h2>
    <p class="sum-top"><span>${svc ? mark("service", svc.name) : "No service yet"}</span>
      <span>${svc ? mark("price", priceText(svc)) : ""}</span></p>
    <p class="sum-sub">${mark("vet", vetText)} · ${mark("time", timeText)}</p>
    ${state.slot
      ? `<button class="btn primary" id="review-btn" data-action="review">Review booking</button>`
      : `<p class="hint">${svc ? "Choose a time to review your booking" : "Choose a service to start"}</p>`}`;
  setBarHeight();
}

function setBarHeight(){
  const bar = $("#bar");
  document.documentElement.style.setProperty("--bar-h", (bar.hidden ? 0 : bar.offsetHeight) + "px");
}
new ResizeObserver(setBarHeight).observe($("#bar"));
render();
</script>
</body>
